        "f7_full": "「米島1-1」の番地が示す通り、旧米島村の中心に鎮座する香取神社。太平洋戦争中の昭和18年（1943年）、疎開してきた服部時計店（精工舎）の工場建設に伴い、この米島に貨物専用の「米島仮停車場（米島駅）」が作られた。戦後の昭和31年（1956年）、西側にあった南桜井駅とこの米島駅が統合されたことで、「米島にある南桜井駅」が誕生したのだ。\n\n見上げるほどの高さを誇る推定樹齢800年の御神木・ムクノキと、甘酒祭りを伝える境内の佇まい。\n\n次は線路を北へ渡り、かつての「南桜井村」エリアである大衾（おおぶすま）の古刹へ。",
