    "name": "急行が通過する街に流れる「自分の時間」——祐天寺、偏愛カルチャーと商店街散歩",
    "description": "中目黒と学芸大学という賑やかな駅に挟まれ、急行電車が軽やかに通過していく祐天寺。だからこそこの街の商店街や路地裏には、誰にも急かされない「自分の好き」を貫く店が集まっている。蒸気機関車の模型がカレーを運ぶ鉄道カフェから、世界大会受賞職人のジェラート、古民家を改装したベーカリースタンド、そして五本木のヴィンテージ古着まで。偏愛と温もりに満ちた5つのしるしを刻む。所要90〜110分・全行程徒歩。",
