        "f7_full": "北国分駅の南口を出て坂道を少し歩くと、香ばしい小麦の香りとともに『石窯パン工房 サフラン 北国分店』のレンガ調の建物が見えてくる。4000年前の縄文から奈良時代へと続く壮大な歴史散策に出発する前に、まずはスペイン製の石窯で次々と焼き上がるカレーパンやハード系ブレッド、季節の菓子パンを手に入れよう。ここで最初のしるしを刻む。\n\n圧倒的な種類を誇る焼きたてパンの棚と、散策前にひと息つける開放的な屋外テラス。\n\n焼きたてのパンを手に入れたら、南西へ歩いて約6分。日本考古学の歴史に名を刻む『堀之内貝塚』の森へ入ろう。",
