        "f7_full": "木漏れ日が差す『堀之内貝塚公園』の地面を踏みしめると、足元の土に白い貝殻のかけらが混じっていることに気づく。今から約4000年前の縄文時代後期、温暖化によってすぐ下の谷まで東京湾の海が入り込み、人々はこの台地の上でハマグリやイボキサゴを採って暮らしていた。明治時代から発掘が行われ、日本考古学で『堀之内式土器』の名前の由来（標式遺跡）となった聖地だ。\n\n足元の黒い土に今も点々と浮かび上がる4000年前の白い貝殻と、馬蹄形に広がる広大な台地の森。\n\n貝塚の森のすぐ隣に佇む『市立市川考古博物館』へ入り、この大地から掘り出された本物の土器や古代の瓦と対面しよう。",
