        "description": "平安時代中期（承平・天慶年間）、平将門が中沢城の鬼門（北東）除け・勝運の守護神として八幡神を鎮祭したと伝わる鎌ケ谷の総守護神。『道野辺』は古街道の『大きな道のほとり』に由来する。",
        "address": "千葉県鎌ケ谷市道野辺中央5-6-10",
        "prefecture": "千葉県",
        "city": "鎌ケ谷市",
        "lat": 35.761412,
