        "f7_full": "JRA競馬学校のすぐ南を走る古道・木下（きおろし）街道沿いに鎮座する『白井木戸天神社』。江戸時代、この街道が幕府の馬牧（小金牧）を通り抜ける出入口に、野生馬が畑へ逃げ出さないよう『木戸（門）』が設けられたことから「白井木戸」「中木戸」という地名が生まれた。そして明治38年（1905年）、この台地に20本あまりの梨の苗木が植えられたことが、全国に誇る『白井の梨』の始まりとなった。なぜ西白井は梨も騎手も育つ街となったのか——その答えを、あなたが選ぶ。\n\n享保15年（1730年）創建の歴史を伝える石祠や記念碑と、神社の周りに広がるみずみずしい梨畑。",
