        "f7_fragment": "小室駅の北口すぐの場所で、広いウッドテラスを構える『小室の茶屋』。",
        "f7_full": "小室駅の北口すぐの場所で、広いウッドテラスを構える『小室の茶屋』。地元の企業が「小室の街にもっと人が集い、語らえる場所を作りたい」という想いから開いた、いわば街の縁側のようなカフェだ。香り高いコーヒーやケーキ、懐かしのナポリタンを味わいながら一息つこう。1万1千年前の縄文の丘から鎌倉の『古牟呂』、そして1979年のニュータウン第一号の街へ、なぜこの小さな台地は時代を超えて愛され続けるのか——その答えを、あなたが選ぶ。\n\n開放的なウッドテラスに流れる穏やかな時間と、地域を想う心から生まれた温かいおもてなし。",
