        "f7_full": "深い木立に包まれた『摩尼珠山（まにじゅさん）松虫寺』。天平年間、難病に倒れた聖武天皇の皇女・松虫姫は、夢のお告げに従って下総国萩原の薬師堂へ参籠し、見事に病を克服した。喜んだ天皇は天平17年（745年）、名僧・行基に命じて七仏薬師を刻ませ、姫の名をとって『松虫寺』を建立させたという。中央の1躯が坐像、左右の6躯が立像という日本でここだけの構成を持つ『木造薬師如来像（七仏薬師）』は国の重要文化財に指定されている。隣接する『松虫姫神社』と姫の御廟にお参りしよう。\n\n松虫姫が突いた杖が根付いたと伝わる『お杖の銀杏』と、1300年の伝説を今に伝える朱塗りの仁王門・松虫姫神社。\n\n参拝を終えたらすぐ隣の森の小径へ。レコード音楽と自家焙煎珈琲が香る隠れ家カフェで北総線の旅を結ぼう。",
