        "f7_full": "田町武家屋敷通りの一角で迎えてくれるのが『あきた角館 西宮家』だ。戦国時代からの武家であり、明治以降は角館の近代化を支えた西宮家の敷地には、太い梁が走る母屋とともに、白壁に黒漆の扉が映える5つの土蔵がずらりと並んでいる。米蔵や文庫蔵に加え、秋田の冬に欠かせない漬物を貯蔵した『ガッコ蔵』までが国の登録有形文化財として残る屋敷を歩こう。\n\n漬物専用に造られた『ガッコ蔵』という秋田ならではの土蔵と、分厚い黒漆塗りの観音扉の重厚感。\n\n商人町と武家町を隔てる広場『火除け』を越えて北へ徒歩9分。道幅と空気が一変する内町（武家屋敷通り）へ足を踏み入れよう。",
