        "f7_full": "夜のネオン看板が並ぶ細い路地へ入ると、石畳の奥から白い湯けむりがもくもくと立ちのぼっている。大正5年（1916年）創設の共同浴場『梅園（ばいえん）温泉』だ。別府には町内会や地域の人々が守る『ジモ泉』と呼ばれる共同浴場が100ヶ所以上もある。この梅園温泉も平成28年（2016年）の地震で一度は建物が壊れたが、「路地の灯りと湯を消すな」と全国のファンと地元の人々が募金を集め、木の香り豊かな湯屋として見事に復活させた。入り口の無料足湯に手を浸し、洗面器が響く音を聞こう。\n\n歓楽街の細い路地の真ん中に温泉神社と足湯があり、洗面器を抱えた地元の人が日常として行き交う光景。\n\n梅園温泉から東へ歩いて2分。大正10年から時が止まったような『日本最古の木造アーケード』へ足を踏み入れよう。",
