        "f7_full": "大通りから一歩路地へ入った瞬間、頭上を覆う古い木組みの屋根に息をのむ。大正10年（1921年）に完成した、日本で現存する最も古い木造アーケード『竹瓦小路（たけがわらこうじ）』だ。かつてすぐ近くの港に着いた大阪商船の船客たちが、雨の日でも傘を差さずに温泉街を歩けるようにと、地元の商店主たちが力を合わせて造り上げた全長約100メートルの通りである。複雑に組まれた木造トラスの天井とすりガラスの天窓、そして別府竹細工のランプシェードが落とすセピア色の光の中を歩こう。\n\n100年以上前の木組みの天井が今も現役の商店街の屋根として頭上に連なり、靴音が静かに反響するノスタルジー。\n\n木造アーケードを南へ通り抜けてすぐ左を向こう。わずか1分先に、城郭のような大唐破風屋根の『竹瓦温泉』が待っている。",
