        "f7_full": "細い竹瓦小路を抜けた正面に、まるで歌舞伎座か城郭のような巨大な屋根がドッと迫ってくる。明治12年（1879年）に竹屋根の湯屋として始まり、昭和13年（1938年）に現在の豪華な『唐破風（からはふ）造』の木造建築へと建て替えられた別府温泉の総本山『竹瓦温泉』だ。正面の優美な曲線を描く大屋根の下をくぐると、高い格天井の番台ロビーが広がり、奥では浴衣姿の人々が温泉熱で温められた砂を掛けてもらう名物『砂湯』で汗を流している。立ちのぼる湯けむりを見上げながら、あなたが惹かれた別府の生き方を選ぼう。\n\n細い路地の突き当たりに突然現れる昭和13年築・大唐破風屋根の圧倒的な存在感と、下足箱が並ぶ高い格天井のロビー。",
