        "f7_full": "小野川の東岸に、川面へ向かって石段の荷揚げ場『だし』が開かれた端正な商家が佇んでいる。国指定史跡『伊能忠敬（いのうただたか）旧宅』だ。17歳で佐原の伊能家に婿入りした忠敬は、酒造や米穀取引で傾きかけていた家業を見事に立て直し、飢饉の際には私財を投げ打って村人を救った名主でもあった。50歳で隠居して江戸へ出たのち、19歳年下の師・高橋至時に天文学を学び、55歳から17年かけて約4万キロを歩き抜くことになる。中庭に立つ天体観測用の石柱『観象台』を見上げよう。\n\n教科書の中の偉人・伊能忠敬が、人生の前半30年以上を凄腕の醸造商人として過ごした生きた生活空間と炊事場の梁。\n\n旧宅の門を出ると、目の前の小野川から涼やかな水音が聞こえてくる。正面に架かる『樋橋（ジャージャー橋）』で旅を結ぼう。",
