        "f7_full": "白と黒のツートンカラーの観光特急『指宿のたまて箱』が発着するJR指宿駅。改札を出て東口広場へ踏み出すと、まぶしい南国の陽射しとともに、高く伸びたビロウ（ヤシ科）の葉が潮風にザワザワと鳴っている。広場のすぐ脇には、地下から湧き出る熱いナトリウム塩化物泉を掛け流した無料の『足湯』が湯気を立てて待っている。かつて西郷隆盛が湯治に訪れ、天璋院篤姫のふるさと（今和泉島津家）としても知られる湯の街の玄関口で、まずは掌や素足に温泉の温もりを伝えて最初のしるしを刻む。\n\n駅を出た徒歩0分の広場に本格的な天然温泉の足湯が湧き、ヤシの木が並ぶ南国リゾート感。\n\n駅前広場から海側の指宿港へ歩いて6分。幕末の薩摩を動かした海運豪商の銅像が立つ『太平次公園』へ向かおう。",
