        "f7_full": "元町公園のすぐ上、目が覚めるようなブルーグレーの下見板張りに、鮮やかなカナリアイエローの柱や窓枠を配した『旧函館区公会堂』がそびえている。明治40年（1907年）の大火で街の集会所が焼失した際、函館の豪商・初代相馬哲平が当時の金額で5万円という巨額の私財を投じ、明治43年（1910年）に完成させた国の重要文化財だ。天井の高い2階の大広間を抜け、正面の大バルコニーへ歩み出ると、眼下に広がる元町公園の緑と、きらめく函館港の大パノラマが迎えてくれる。潮風に吹かれながら、あなたの心に一番残った函館の風景を選ぼう。\n\n北国の青空に映えるブルーグレー×黄金色の大胆な色彩美と、2階バルコニーから函館湾を見晴らす王侯貴族のような視界。",
