        "f7_full": "平泉駅から西へ歩いて8分、視界が大きく開けた緑の芝生の中に、静かな水面をたたえた『観自在王院跡（かんじざいおういんあと）』が現れる。12世紀中頃、奥州藤原氏2代・藤原基衡（もとひら）の妻が建立した寺院跡で、現在は世界遺産の構成資産として誰でも自由に歩ける浄土庭園だ。大きな『舞鶴が池』のほとりに立つと、北の空に端正な円錐形を描く信仰の山『金鶏山（きんけいさん）』が池の借景としてくっきりと浮かび上がる。平安の貴婦人が思い描いた極楽の風景の中で、最初のしるしを刻む。\n\n塀や門に遮られない広大な芝生の真ん中に、850年前の平安時代の池と滝石組がそのまま残されている開放感。\n\n観自在王院跡のすぐ西隣へ徒歩3分。平安時代の『遣水』が今もせせらぎを奏でる世界遺産『毛越寺』の門をくぐろう。",
