        "f7_full": "有田駅から皿山通りの町並みを抜けて北東へ（コミュニティバスやレンタサイクル、隣の上有田駅からのアプローチも心地よい）、白川川に沿う静かな通りへ入ると、煉瓦の煙突と『陶祖李参平公住居跡』の石碑が立つ『李荘窯業所（りそうようぎょうしょ）』が見えてくる。元和2年（1616年）、朝鮮半島から渡来した陶工・李参平（り・さんぺい）が泉山で白い磁石を発見し、日本で初めて透き通るような『白磁』を焼き上げた歴史的な住居跡だ。江戸初期の『初期伊万里』の陶片研究から、現代の三つ星レストランを彩る球体型の有田焼まで、400年の進化が息づく工房の前で最初のしるしを刻む。\n\nかつて土器や陶器しか作れなかった日本で初めて純白の『磁器』を生んだ陶祖の住居跡で、今も現役の窯が火を灯し続けている生きた歴史。\n\n白川の里から南へ歩いて5分。重要伝統的建造物群保存地区の表通り『皿山通り』へ出て、名窯『香蘭社』の洋館を訪ねよう。",
