        "f7_full": "皿山通りから南東へ折れると、町の人々から「とうざんさん」と親しまれる『陶山（すえやま）神社』の石段が始まる。驚いたことに、参道の石段のすぐ途中をJR佐世保線の線路が横切っており、遮断機のない踏切の向こうにさらなる石段が続いている。左右を確かめて線路を渡り、石段を登りきった先にそびえているのが、昭和4年（1929年）に有田の陶工たちが奉納した高さ約3.7メートルの『磁器の大鳥居』（国登録有形文化財）だ。\n\n柱から笠木まですべて純白の有田焼の筒を繋いで造られた青白磁の大鳥居と、狛犬・大水瓶・欄干・お守りまで焼き物で揃う日本唯一の光景。\n\n陶山神社の石段を下りて北西の裏通りへ徒歩3分。赤茶色の『トンバイ塀のある裏通り』と『アリタポーセリンラボ』で旅を結ぼう。",
