    "description": "昭和37年のまちびらき以来、日本初の本格的大規模ニュータウンとして歩車分離の都市計画を実現した大阪・吹田の桃山台（ももやまだい）。駅の大きな歩道橋を渡るとすぐ眼下に広がる江戸期以来のため池『桃山公園 春日大池』から、開発前の千里丘陵の原風景を封じ込めた『千里の竹林（桃山公園の孟宗竹林）』へ。車道を一度も渡らない緑道を抜けて昭和40年代の近隣センター『竹見台マーケット』の温かな活気に触れ、パリの公園を模した『千里南公園 円形広場とメタセコイア並木』から雨乞い伝承の『千里南公園 牛ヶ首池とカリヨン塔』へ至る。西から東へ一筆書きで抜ける全行程徒歩・約1.8km。",
