        "description": "平成13年（2001年）開館、建築家・伊東豊雄氏の代表作。定禅寺通のケヤキ並木から着想を得た13本の白い網目状鉄骨チューブ（柱）が7層の床と全面ガラスの外壁を貫く世界的現代建築。",
