        "f7_full": "地下鉄勾当台公園駅のすぐ上、石組の人工滝が涼やかな水音を立てる『古図広場』の床面を見下ろすと、広場全体の石畳に江戸時代初期の古地図『寛文四年（1664年）仙台城下絵図』が巨大な陶板で精密に焼き付けられている。今歩いてきた定禅寺通やこれから向かう一番町の道筋を、400年前の侍屋敷・町人町の区画と自分の足元で見比べることができ、仙台の街の骨格が江戸初期から寸分違わず残っていることに驚かされる。\n\n「勾当台」という風雅な地名が、伊達政宗公に仕えた盲目の狂歌師・花村勾当の屋敷がこの高台にあったことに由来し、のちに仙台藩最大の藩校「養賢堂」が置かれた学問の地だったこと。\n\n広場の南側から一番町四丁目へ南へ徒歩6分。元料亭の黒板塀が迎える路地奥の『甘味処 彦いち』へ入ろう。",
