        "f7_full": "大正14年（1925年）にこの路地の入口に開館した活動写真館「文化キネマ」にその名を由来する『文化横丁』。肩が触れ合うほど細い路地に約50軒の小さな店がひしめくその最奥に、大きな白提灯と紺暖簾を掲げる昭和25年（1950年）創業の名酒場『源氏』が佇んでいる。飴色に磨かれた「コの字カウンター」に腰を下ろせば、割烹着姿の女将がつける宮城の地酒の燗と、一杯ごとに変わる季節のお通しが、杜の都の夜を静かに温めてくれる。\n\n戦後間もない昭和25年の創業以来、酒を一杯頼むごとに季節のお通しが順番に1品ずつ（最大4杯・4品まで）供される独自の習わしが75年以上受け継がれていること。",
