        "f7_full": "白樺林を抜けて駅前通りへ出ると、1982年からこの駅前で暖簾を守る酒店『西沢商店』に行き着く。扉を開けると、北海道内の酒蔵が醸した地酒やクラフトビール、そして北国の冷え込む夜にじんわりと身体を温める「お燗向きの純米酒」が丁寧に温度管理されて並んでいる。宿や帰りの汽車で味わう小瓶や、旅の記憶を持ち帰る一本を店主と語らいながら選ぶ時間が、列車待ちのひとときを豊かに彩ってくれる。\n\n人口の少ない阿寒摩周の温泉駅の目の前にありながら、全国の純米酒蔵から直接仕入れるラインナップの深さから、道東一円の料理人や酒好きがわざわざ列車や車で買いに訪れる隠れた名酒店となっている。\n\n旅の一本を鞄に忍ばせたら東へ徒歩1分。白樺木立のなかで甘い香りを漂わせる『森のホール』へ立ち寄ろう。",
