        "f7_full": "運河跡を越えた瞬間、道幅は大人が両手を広げれば届きそうな一間（約1.8メートル）ほどの細い路地へと変わり、潮の匂いを孕んだ迷路が縦横に走り始める。切妻造りの黒板壁が続く家々の軒先を見上げると、丸印に漢字や記号を書いた小さな木製の「飛び出し看板」が一斉に通りへと突き出している。路地の奥に鎮座する『飛鳥神社』の深い木立まで歩けば、海と共に生きてきた濃密な共同体の息遣いが肌で伝わってくる。\n\n軒先に並ぶ不思議な「飛び出し看板」は、限られた砂州の島に同じ苗字の漁師世帯が何十軒も暮らしていたため、郵便配達や来客が「屋号」で家をすぐに見分けられるようにと生まれた暮らしの知恵なのだ。\n\n漁師町の路地を東北東へ徒歩10分。溜まり醤油と生姜の甘辛い香りが漂う天カ須賀の『貝新商店』へ進もう。",
