        "f7_full": "一日数十万人が早足で行き交う大宮駅東口を出て、青白いアーチが連なる『すずらん通り』を抜けると、二十四時間三百六十五日一度も明かりを消さずに旅人を迎え続ける大箱の純喫茶『伯爵邸』が現れる。シャンデリアとステンドグラスが輝く店内で、隣の席から漂う名物「大宮ナポリタン」の香ばしい湯気に包まれながら、まずは淹れたてのサイフォン珈琲とモーニングのトーストで目を覚まそう。北の玄関口・大宮の混沌としたエネルギーをひと口吸い込んだら、「減速の旅」の始まりだ。\n\nかつて国鉄大宮工場の職人や夜行列車を待つ旅人で昼夜なく賑わった「鉄道の街・大宮」の気風が、今も眠らない純喫茶とご当地ナポリタンの文化として息づいている。\n\n駅前の喧騒を背に北東へ徒歩12分。ケヤキの大樹が空を覆う『氷川参道と氷川だんご屋』へ歩を進めよう。",
