        "f7_full": "ビル街を抜けて『氷川参道』の石畳へ足を踏み入れた瞬間、頭上を覆う巨大なケヤキの葉陰によって日差しの温度がすっと下がり、車の音が遠ざかる。三の鳥居の手前で白い煙と香ばしい醤油の匂いを漂わせているのが『氷川だんご屋』だ。赤い毛氈の縁台に腰を下ろし、砂糖を使わず醤油だけで香ばしく焼き上げた熱々の団子と緑茶をいただけば、早足だった都会の歩調が自然と木漏れ日のリズムへとほどけていく。\n\n南北約二キロメートルにわたって続くこの氷川参道は、日本一長いケヤキ並木の参道であり、樹齢数百年を超える古木約六百五十本が街の真ん中に巨大な緑の回廊をつくっているのだ。\n\nケヤキのトンネルを北北西へ徒歩7分。朱塗りの太鼓橋が水面に映える『武蔵一宮 氷川神社（神橋と楼門）』へ入ろう。",
