    "description": "赤いディーゼル列車がガタゴトと走り去ると、白壁と下見板張りの木造駅舎・善導寺駅には筑後平野の穏やかな風が吹き抜ける。駅前の踏切を渡って旧筑後街道へと北へ歩けば、バーナーで炙る甘いキャラメルの香りと玉露の銘菓が旅人を迎え、その先には樹齢八百年の大楠と国の重要文化財の大伽藍が静かに待ち構えている。最後は門前集落の微高地から、南の空を屏風のように仕切る耳納連山の稜線を仰ぐ門前町さんぽ。",
