        "f7_full": "ゆいレール儀保駅を降りてすぐ北の路地へ入ると、南国の陽光を受けた『臨済宗 盛光寺（せいこうじ）』の静かな境内が現れる。ここは沖縄県民なら誰もが知る首里名物「のまんじゅう（ぎぼまんじゅう）」が生まれた伝説の場所だ。かつてこの山門の脇で蒸し器の湯気が白く立ち上り、月桃（サンニン）の葉の爽やかな香りが通りいっぱいに漂っていた記憶を辿りながら、赤瓦が輝く穏やかな本堂に手を合わせよう。\n\n白い生地に食紅で大きく熨斗（のし）を表す『の』の字を書く名物『ぎぼまんじゅう』は、もともとこの盛光寺の敷地内の小さな売店から始まり、その地名がそのまま屋号となった。\n\n盛光寺から南南西へ徒歩1分。今も駅前の通りで伝統の餅を並べる『首里餅菓子屋 儀保店』へ立ち寄ろう。",
