          "text": "毎年一月に竹筒を釜で炊き、中に入った米粒の数で十二ヶ月の豊凶を占う式内社「小古曽神社」",
          "description": "『小古曽神社（小許曽神社）』の静かな杜を歩き、千年以上の歴史をもつ農耕神事「粥試し」の伝承に耳を傾けるひと時",
          "badge_code": "shuin_ogoso_kayudameshi_shrine"
