        "f7_full": "高田越えの坂の途中に、フランス・ロワール地方の古い館をモチーフにした石積みの洋館カフェ『amboise（アンボワーズ）』が忽然と姿を現す。重厚な木製扉を開けると、アンティーク家具とドライフラワーに彩られた非日常の空間が広がっている。サクサクのパイ生地に具材が詰まった焼きたてのキッシュや、宝石のように美しい季節のタルトと紅茶を味わいながら、高田郷の小さな旅を優雅に締めくくろう。\n\n店名の『アンボワーズ』はルネサンス文化が花開いたフランス・ロワール渓谷の古都に由来し、敷地内にはドーナツ専門店なども並ぶ高田郷屈指のグルメスポットとなっている。",
