        "f7_full": "暖簾をくぐると、鰹節と昆布を合わせた出汁の芳醇な香りが優しく迎えてくれる『石臼そば 安曇野 巣子店』。こちらの自慢は、選び抜いた玄蕎麦を熱を持たせないよう石臼でゆっくりと挽き上げた香り高い手打ち蕎麦だ。せいろの上に瑞々しく盛られた細打ちの蕎麦は、まずはつゆをつけずにそのまま一箸手繰れば、穀物の甘い香りと爽やかな喉越しが口いっぱいに広がる。揚げたての天ぷらや濃厚なそば湯とともに、高原の街歩きの締めくくりを堪能しよう。\n\n冷涼で水はけのよい火山灰土壌が広がる岩手県北部〜滝沢周辺は古くから良質な玄蕎麦の産地として知られ、高冷地の人々の命を繋いできた蕎麦は今もこの土地の誇りである。",
