        "f7_full": "橋を渡って球磨川の左岸へ出ると、100年以上にわたり渓谷の旅人を見守ってきた木造建築と『白石の渡し跡（白石渓谷河畔）』が現れる。そもそも「白石」という美しい地名は、対岸の山肌に真っ白な石灰岩（白石）の巨岩が露出していたことに由来する。かつてはここで焼かれた石灰が川舟に積まれ、遠く天草や島原まで運ばれた。河畔で川風に吹かれながら、白い断崖とエメラルドグリーンの水面の対比を眺めよう。\n\n人吉まで鉄道が開通する以前、この白石周辺は川舟から鉄道へと荷物を積み替える水陸接続の要衝として賑わい、開業時の風格を残す木造駅舎は映画やCMのロケ地としても愛されている。\n\n川風でひと息ついたら南南東へ徒歩12分。再び球磨川の右岸・神瀬の崖下へと向かい、二億年の歳月が造り上げた『神瀬石灰洞窟（国指定名勝・岩戸熊野座神社）』の入り口へ踏み込もう。",
