        "f7_full": "天王神社から続く台地へ入ると、幾重にも巡らされた巨大な空堀（からぼり）と土塁が往時の威容を今に伝えている。北奥羽の覇権をめぐって南部一族がしのぎを削った中世の巨城『国指定史跡 七戸城跡』だ。本丸・二の丸・三の丸など7つもの曲輪（くるわ）が複合した城郭は、1591年に豊臣秀吉の奥州仕置軍と戦った「九戸政実の乱」で歴史の転換点を迎え、その後は盛岡藩の代官所として再生した。復元された東門とケヤキ並木を歩こう。\n\n「七戸」をはじめとする「一戸〜九戸」の地名は、中世に朝廷へ献上する駿馬（南部駒）を育てた行政区画・牧（まき）の編成に由来するといわれ、1941年に国の史跡に指定されている。\n\n城跡の空堀と土塁を巡ったら東南東へ徒歩4分。坂を下って旧奥州街道の宿場通りへ出たら、地元で愛される『赤牛食堂』の暖簾をくぐろう。",
