        "f7_full": "旧山陰街道が桂川の渡しへと向かう要衝に、赤い提灯が揺れる『地蔵寺（桂地蔵）』の山門が現れる。本尊の地蔵菩薩立像は、852年に小野篁（おののたかむら）が冥土で出会った生身の地蔵尊を1本の巨木から6体彫り出し、のちに平清盛が都の6つの街道口へ分祠した「京都六地蔵」のひとつだ。大木の最も根元に近い部分で刻まれた身の丈約2.6メートルの「姉井（あねい）地蔵」を見上げ、旅人の無事を祈った街道の歴史に耳を澄まそう。\n\n毎年8月22日・23日の「六地蔵めぐり」では、都の6つの入口にある地蔵尊を巡って6色の「お幡（おはた）」を授かり、家の玄関に吊るして一年間の無病息災を祈る風習が800年以上続いている。\n\n桂地蔵に手を合わせたら北北東へ徒歩6分。桂離宮の外周に沿って、生きた竹をそのまま編み込んだ緑の垣根が続く『桂離宮（桂垣と竹林の道）』へ歩みを進めよう。",
