        "f7_full": "旧街道から桂川の方へ歩みを進めると、道路に沿って鮮やかな緑の壁がうねるように続く『桂離宮』の外周に出る。ここに張り巡らされている「桂垣（笹垣）」は、地面に生えたままの孟宗竹を地上2メートルほどの高さで水平に折り曲げ、割竹の骨組みに生きている枝葉ごと編み込んで仕立てた唯一無二の生垣だ。さらに北側の表門へと回れば、皮付きの丸太柱に割竹を隙間なく並べた端正な「穂垣」と清らかな玉砂利の道が凛とした気配を放っている。\n\n全長約250メートルにおよぶ桂垣は、枯れた竹ではなく地面に根を張ったままの「生きた竹」を植木職人が毎年秋に編み直すことで、400年にわたり青々とした姿を保ち続けている。\n\n生きた竹垣の造形美を堪能したら東南東へ徒歩3分。桂大橋のたもとで1883年から暖簾を掲げる老舗『御菓子司 中村軒』へ向かおう。",
