        "f7_full": "神通川と高原川が合流する深い山あいに佇む『猪谷駅』から国境の旅を始めよう。ここは富山県（越中）と岐阜県（飛騨）の県境に位置し、JR西日本とJR東海の会社境界駅として特急「ひだ」も停車する鉄道の要衝だ。かつてはここから飛騨の神岡鉱山へと続く「旧神岡鉄道」が分岐し、亜鉛や鉛の鉱石、硫酸を積んだ貨物列車が峡谷の鉄橋を渡っていた。静かな島式ホームと駅舎の前に立つと、山国の物流を支えた鉄路の鼓動が今もかすかに響いてくる。\n\n1930年に飛越線として開業した猪谷駅は、神岡鉱山の物資輸送のために三井鉱山が敷設した馬車軌道（神岡軌道）との積み替え拠点として大いに賑わった歴史を持つ。\n\n国境駅の空気を味わったら東南東へ徒歩1分。駅前広場のすぐ向かいに建つ『富山市猪谷関所館』へ足を踏み入れよう。",
