        "f7_full": "公園のすぐ隣に、4門のローラーゲートが重厚な影を落とす『家地川取水堰（通称：家地川ダム）』が横たわっている。1937年に築かれたこの堰は、標高の高い山あいを蛇行する四万十川本流の水を取り込み、南側の山脈を貫く導水トンネルを通って、直線距離で数キロしか離れていない太平洋側（黒潮町）の伊与木川水系・佐賀発電所へと一気に落として水力発電を行うための要衝だ。ゴウゴウと白泡を立てて越流する水の力強さと、戦前の石積み・コンクリート技術を間近に観察してみよう。\n\n緩やかに大回りして流れる四万十川と、すぐ南側の急斜面を太平洋へ直滑降する伊与木川との「標高差（約150m以上の落差）」に目をつけた、地形のトリックを活かした流域変更型の発電施設である。\n\n分水堰の仕組みに唸ったら東北東へ徒歩5分。家地川集落の産土神として守り継がれてきた『河内神社』へ歩みを進めよう。",
