        "f7_full": "北陸新幹線の白い高架橋を見上げる越前たけふ駅の改札を出て、すぐ隣に立つ『道の駅 越前たけふ』から旅を始めよう。木の格子をあしらった館内に足を踏み入れると、700年の歴史を持つ「越前打刃物」の鋭い槌目（つちめ）模様が輝く包丁や、柔らかな風合いの越前和紙、そして武生エリアの老舗が作る羽二重餅や水ようかんなどの銘菓がずらりと並んでいる。職人のまち・越前の手仕事を眺め、旅の伴にする小さな土産を探してみよう。\n\n新幹線の単独駅と道の駅が駅前ロータリーを共有して一体整備された全国でも珍しい構造で、駅舎と道の駅の双方に越前和紙や越前指物の意匠が取り入れられている。\n\n越前の手仕事に触れたら西へ徒歩8分。村国山の東麓に抱かれた『大屋町の宮座ゆかりの里』へ向かおう。",
