        "f7_full": "高架駅から西へ歩き、村国山の緑が迫る大屋町の集落へ入ると、氏子から選ばれた当屋が一年間精進潔斎して神事を営む中世以来の祭祀組織「大屋町の宮座」が受け継がれてきた里に出る。背後の山裾には、6世紀後半の円墳の横穴式石室に1501年（明応10年）銘の地蔵石仏群を祀った珍しい史跡「穴地蔵古墳」も眠っている。古代の石室を後世の人々が祈りの場として守り継いだ、大屋町ならではの重層的な歴史を感じ取ろう。\n\n新幹線の最新駅が立つすぐ西側の集落に、500年以上続く中世の宮座行事と、6世紀の巨石石室・16世紀初頭の年号入り石仏が一体となった「二時代複合の史跡」が静かに守られている。\n\n宮座と古墳の里を後にしたら北北西へ徒歩14分。かつて越前国府の総社の鍵番を務めた葛岡町の『神明神社』を訪ねよう。",
