        "f7_full": "海岸線すれすれを走る広電宮島線の阿品東駅のすぐ隣、建物の外階段を上って2階の『kitchen & drink yuba（ユバ）』の扉を開けよう。店内に足を踏み入れると、壁一面の大きな窓の向こうに、牡蠣筏が浮かぶ穏やかな大野瀬戸の海と厳島（宮島）の緑の島影が広がっている。時折、真下の線路をゴトゴトと駆け抜ける路面電車の屋根を見下ろしながら、名物のアヒージョやパスタ、ランチプレートで海辺の食事を楽しもう。\n\n広電宮島線のこの区間は、海岸の護岸のすぐ上を複線の線路が走る全国でも屈指のシーサイド区間であり、2階の窓辺からは「路面電車・瀬戸内海・宮島」の三つが重なる独特の構図を眺められる。\n\n海辺の窓辺で食事を楽しんだら北へ徒歩19分。対岸の厳島神社と対をなす外宮『地御前神社』を訪ねよう。",
