        "f7_full": "海沿いの宮島街道の松並木の名残を感じながら北へ進むと、海のほうへ開けた石鳥居と風格ある社殿を持つ『地御前神社』に到着する。「厳島神社の外宮（げくう）」として崇敬を集めるこの社は、神の島としてかつて人が容易に立ち入れなかった厳島を、本土の「地の御前（手前）」から遥拝するために建てられたのが始まりと伝わる。潮風が揺らす境内の木立に佇み、海を隔てて宮島の本宮と一直線に向き合う祈りの軸線を感じ取ろう。\n\n毎年旧暦6月17日に行われる日本三大船神事「管絃祭」では、夕刻に宮島を出発した御座船が大野瀬戸を横断してまずこの地御前神社前の浜（御笠浜）へ着岸し、雅楽と火かりの中で大祭が執り行われる。\n\n外宮の社殿に参拝したら東へ徒歩6分。地御前漁港のそばで牡蠣の直売を営む『峠水産』で旅を結ぼう。",
